import{_ as e,o as t,c as o,ag as i}from"./chunks/framework.DMXcdKmJ.js";const f=JSON.parse('{"title":"导入工程","description":"在工程管理里用 .ifproj 或 .ifbatch 归档导入已有工程，说明入口、预览和常见被拒原因。","frontmatter":{"title":"导入工程","description":"在工程管理里用 .ifproj 或 .ifbatch 归档导入已有工程，说明入口、预览和常见被拒原因。","kind":"how-to","status":"reviewed"},"headers":[],"relativePath":"zh/guide/import-project.md","filePath":"zh/使用指南/导入工程.md"}'),r={name:"zh/guide/import-project.md"};function d(l,a,h,c,n,s){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="导入工程" tabindex="-1">导入工程 <a class="header-anchor" href="#导入工程" aria-label="Permalink to &quot;导入工程&quot;">​</a></h1><p>迁移或接收已有工程时，用工程归档文件导入，而不是在应用开发里上传压缩包。本页说明入口、支持的格式和常见问题。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>已登录并打开左侧“工程管理”，且账号有管理工程的权限。</li><li>手上是 <code>.ifproj</code>（单个工程）或 <code>.ifbatch</code>（批量包）归档文件。普通 <code>.zip</code> 不能用于导入。</li></ul><h2 id="入口" tabindex="-1">入口 <a class="header-anchor" href="#入口" aria-label="Permalink to &quot;入口&quot;">​</a></h2><ol><li>打开左侧“工程管理”，进入工程概览。</li><li>在列表上方的工具栏里找到<strong>导入工程</strong>按钮（上传图标，悬停显示“导入工程”），点击后选择归档文件。</li><li>选择完成后先进入<strong>导入预览</strong>，确认无误再执行导入。</li></ol><h2 id="支持的文件" tabindex="-1">支持的文件 <a class="header-anchor" href="#支持的文件" aria-label="Permalink to &quot;支持的文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>说明</th><th>选择方式</th></tr></thead><tbody><tr><td><code>.ifproj</code></td><td>单个工程的完整归档，包含工程信息、配置与工作区源码</td><td>可一次多选多个，逐个预览后导入</td></tr><tr><td><code>.ifbatch</code></td><td>批量分发包，内含多个工程</td><td>一次只能选一个，且不能与其他文件混选</td></tr></tbody></table><p>普通 <code>.zip</code>、旧 <code>.json</code> 归档和文件夹都不接受：压缩包请先按归档格式导出为 <code>.ifproj</code>，旧 JSON 归档已停用。</p><h2 id="预览并确认" tabindex="-1">预览并确认 <a class="header-anchor" href="#预览并确认" aria-label="Permalink to &quot;预览并确认&quot;">​</a></h2><ul><li>预览会显示工程名称、包体积、条目数、配置行数、运行用户数；批量包还会显示包含的工程数量。</li><li>确认内容后执行导入；导入过程中不要重复点击。</li><li>批量包部分成功时，列表会刷新显示已导入的工程，结果提示同时列出成功和失败项。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li>提示“请选择 .ifproj 或 .ifbatch 工程归档文件”：选错了文件，换成归档文件重试。</li><li>提示“旧 JSON 归档已停用，请使用 .ifproj”：把旧归档按当前格式重新导出后再导入。</li><li>提示“未找到 project.json / 工程数据格式不正确”：归档不完整或已损坏，请重新导出或向交付方索取完整包。</li><li>导入后看不到工程：确认当前组织和权限，并刷新工程列表。</li></ul><h2 id="与上传文件的区别" tabindex="-1">与上传文件的区别 <a class="header-anchor" href="#与上传文件的区别" aria-label="Permalink to &quot;与上传文件的区别&quot;">​</a></h2><ul><li><strong>导入工程</strong>：用 <code>.ifproj</code> / <code>.ifbatch</code> 创建一个完整工程，出现在工程列表里。</li><li><strong>上传文件</strong>：在已有工程的应用开发里上传 <code>.zip</code> 等普通文件，只写入该工程的工作区，不会创建新工程；见<a href="/induframe-docs/zh/guide/upload-files">在应用开发中上传文件</a>。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>导入完成后打开工程，在<strong>应用开发</strong>里继续编辑或让 AI 助手修改；账号与入口说明见<a href="/induframe-docs/zh/guide/login">登录与退出</a>。</p>',17)])])}const p=e(r,[["render",d]]);export{f as __pageData,p as default};
